#include <stdio.h>

struct Cat {
    char name[20];
    int fish;
};

int main(void) {
    struct Cat cats[5] = {
        {"张三", 0},
        {"李四", 0},
        {"计算机", 0},
        {"三花", 0},
        {"墨墨", 0}
    };
    int n;

    if (scanf("%d", &n) != 1) {
        return 1;
    }
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &cats[i].fish) != 1) {
            return 1;
        }
    }

    struct Cat *best = cats;
    for (struct Cat *p = cats; p < cats + n; p++) {
        if (p->fish > best->fish) {
            best = p;
        }
    }

    printf("%s 处理得最多，%d 条\n", best->name, best->fish);
    return 0;
}

