#include <stdio.h>

struct Cat {
    char name[20];
    int fish;
};

void feed(struct Cat *c, int n) {
    c->fish = c->fish + n;
}

int main(void) {
    struct Cat a = {"张三", 2};

    printf("%s 处理了 %d 条\n", a.name, a.fish);
    feed(&a, 3);
    printf("喂过之后 %s 处理了 %d 条\n", a.name, a.fish);
    return 0;
}

