#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct Cat {
    char name[20];
    int fish;
};

int main(void) {
    struct Cat *p = (struct Cat *)malloc(sizeof(struct Cat));

    if (p == NULL) {
        printf("变量没租到\n");
        return 0;
    }

    strcpy(p->name, "张三");
    p->fish = 3;
    printf("%s 有 %d 条\n", p->name, p->fish);

    free(p);
    p = NULL;
    return 0;
}

